function applyRadioTrack(track){
  const player=document.querySelector("#party-radio-player");
  if(!player||!track?.mediaUrl)return;
  player.volume=radioVolume;
  if(player.src!==track.mediaUrl){
    player.src=track.mediaUrl;
    const seek=()=>{if(track.elapsedSeconds>0)player.currentTime=track.elapsedSeconds;player.removeEventListener("loadedmetadata",seek);};
    player.addEventListener("loadedmetadata",seek);
    player.play().catch(()=>{});
  }
}
function stopRadioVisualizer(){cancelAnimationFrame(radioAnimationId);radioAnimationId=null;radioSourceElement=null;}
function setupRadioVisualizer(){
  const canvas=document.querySelector("#party-radio-canvas"),audio=document.querySelector("#party-radio-player");
  if(!canvas||!audio){stopRadioVisualizer();return;}
  audio.volume=radioVolume;
  if(radioSourceElement===audio)return;
  try{
    radioAudioCtx??=new (window.AudioContext||window.webkitAudioContext)();
    if(radioAudioCtx.state==="suspended")radioAudioCtx.resume().catch(()=>{});
    const source=radioAudioCtx.createMediaElementSource(audio);
    radioAnalyser=radioAudioCtx.createAnalyser();
    radioAnalyser.fftSize=64;
    source.connect(radioAnalyser);
    radioAnalyser.connect(radioAudioCtx.destination);
    radioSourceElement=audio;
    const data=new Uint8Array(radioAnalyser.frequencyBinCount),ctx2d=canvas.getContext("2d");
    cancelAnimationFrame(radioAnimationId);
    const draw=()=>{
      if(!document.body.contains(canvas)){stopRadioVisualizer();return;}
      radioAnimationId=requestAnimationFrame(draw);
      radioAnalyser.getByteFrequencyData(data);
      ctx2d.clearRect(0,0,canvas.width,canvas.height);
      const barWidth=canvas.width/data.length;
      for(let i=0;i<data.length;i++){const barHeight=(data[i]/255)*canvas.height;ctx2d.fillStyle="rgba(255,255,255,0.75)";ctx2d.fillRect(i*barWidth,canvas.height-barHeight,barWidth-2,barHeight);}
    };
    draw();
  }catch{}
}
function spawnRadioReaction(reaction,name){
  const host=document.querySelector("#party-radio-reactions");
  if(!host)return;
  const emojis={like:"👍",heart:"❤️",fire:"🔥",clap:"👏"},node=document.createElement("div");
  node.style.cssText=`position:absolute;left:${10+Math.random()*70}%;bottom:0;text-align:center;animation:party-reaction-float 2.2s ease-out forwards`;
  node.innerHTML=`<span style="font-size:22px">${emojis[reaction]||"👍"}</span>${name?`<div style="font-size:10px;font-weight:700;white-space:nowrap;color:var(--muted)">${name}</div>`:""}`;
  host.append(node);
  setTimeout(()=>node.remove(),2200);
}
let radioSyntheticTimer=null;
function stopSyntheticRadioReactions(){if(radioSyntheticTimer){clearTimeout(radioSyntheticTimer);radioSyntheticTimer=null;}}
function scheduleSyntheticRadioReaction(){
  if(!document.querySelector("#party-radio-reactions")||!state.partyCurrentTrack){radioSyntheticTimer=null;return;}
  const listeners=Math.max(20,state.partyListenerEstimate||2000);
  const reactionsPerMinute=Math.max(2,listeners*0.01/10);
  const delay=Math.max(1500,Math.min(20000,60000/reactionsPerMinute*(0.5+Math.random())));
  radioSyntheticTimer=setTimeout(()=>{
    const reactions=["like","heart","fire","clap"];
    spawnRadioReaction(reactions[Math.floor(Math.random()*reactions.length)],createFriendlyHandle());
    scheduleSyntheticRadioReaction();
  },delay);
}
function updateRadioMediaSession(track){
  if(!("mediaSession" in navigator))return;
  if(!track){navigator.mediaSession.metadata=null;navigator.mediaSession.playbackState="none";return;}
  navigator.mediaSession.metadata=new MediaMetadata({title:track.title||"Radio",artist:track.artistName||"SunoTo Radio",artwork:track.artworkUrl?[{src:track.artworkUrl,sizes:"512x512"}]:[]});
  navigator.mediaSession.playbackState="playing";
  navigator.mediaSession.setActionHandler("play",()=>document.querySelector("#party-radio-player")?.play().catch(()=>{}));
  navigator.mediaSession.setActionHandler("pause",()=>document.querySelector("#party-radio-player")?.pause());
  navigator.mediaSession.setActionHandler("nexttrack",()=>partyClient?.send("RADIO_SKIP_VOTE",{}));
}
