async function pollSearch(){if(routeName()!=="searching"||!state.anonymousSession)return;try{const result=await pollMatchResult(state.anonymousSession.token);if(result.status==="matched")return openMatch(result);if(result.status==="idle"&&state.searchMode!=="reconnect")throw new Error("Search ended before a match was found.");searchPollId=setTimeout(pollSearch,1000);}catch(error){state.searchError=error.message;render();}}
