async function cancelCurrentSearch(){clearTimeout(searchPollId);if(state.anonymousSession){const cancel=state.searchMode==="reconnect"?cancelFavouriteReconnect:cancelMatch;await cancel(state.anonymousSession.token).catch(()=>{});}state.searchError="";state.searchMode="random";state.chatMode="text";navigate("home");}
async function startFavouriteReconnect(peerId){await ensureAccountAuth();if(!state.accountSession?.user?.email_confirmed_at){state.accountMessage="Sign in and verify your email before reconnecting.";return navigate("account");}await ensureAnonymousSession();const result=await requestFavouriteReconnect({anonymousToken:state.anonymousSession.token,accountSession:state.accountSession,targetPeerId:peerId});if(result.status==="offline")throw new Error("That favourite is not online right now.");state.searchMode="reconnect";state.searchError="Waiting for your favourite to accept…";navigate("searching");searchPollId=setTimeout(pollSearch,700);}
