async function refinePreciseWeather(){if(state.featureFlags?.weather_enabled===false)return;if(!navigator.geolocation)return;try{const data=await preciseWeather();state.weather={temperatureC:Math.round(data.temperatureC),label:weatherLabel(data.weatherCode)};render();}catch{}}
function currentPresenceSection(){const route=routeName();if(route==="chat")return videoCall?"video_chat":"text_chat";if(route==="searching")return"searching";if(route==="party")return state.partyRoom?"party_room":"party_lobby";return"home";}
async function maintainPresence(){try{await ensureAnonymousSession();const route=routeName(),status=route==="chat"?"chatting":route==="searching"?"waiting":"online";await heartbeatPresence(state.anonymousSession.token,status,{accountSession:state.accountSession,section:currentPresenceSection()});}catch{}presenceTimer=setTimeout(maintainPresence,20000);}
