function tickActiveUsers(){state.activeUsersDisplay=randomActiveCount()+(state.publicStats?.realActiveSessions||0);state.registeredUsersDisplay=registeredUserCount(state.publicStats?.registeredUsers||0);const badge=document.querySelector(".active-users");if(badge)badge.innerHTML=`<span class="active-dot"></span>${state.activeUsersDisplay.toLocaleString("en-IN")} online`;else render();activeUsersTimer=setTimeout(tickActiveUsers,3000+Math.random()*4000);}
function tickRadioListeners(){clearTimeout(radioListenerTimer);if(routeName()!=="party"||state.partyRoom||!state.radioChannels.length){radioListenerTimer=setTimeout(tickRadioListeners,8000);return;}const display={};for(const channel of state.radioChannels)display[channel.publicId]=(channel.realListeners||0)+nextRadioListenerCount(channel.publicId);state.radioListenerDisplay=display;render();radioListenerTimer=setTimeout(tickRadioListeners,8000+Math.random()*4000);}
async function refreshAdConfig(){try{const snapshot=await loadPublicAdSnapshot();state.featureFlags=snapshot.flags;state.membershipConfig=snapshot.membership||state.membershipConfig;state.adEarningConfig=snapshot.adEarning||state.adEarningConfig;if(snapshot.version!==state.adConfigVersion){state.adConfig=snapshot.config;state.adConfigVersion=snapshot.version;mountAds(document,{config:state.adConfig,registered:Boolean(state.accountSession),balance:state.wallet?.balance||0,scanCount:routeName()==="party"?0:state.scanCount});}}catch{}adConfigTimer=setTimeout(refreshAdConfig,30000);}
async function finishChat(reason="ended",destination="history",notifyServer=true){if(finishingChat)return;finishingChat=true;clearInterval(chatTimerInterval);chatTimerInterval=null;chatTimerRemaining=null;stopVideoCall(false);if(notifyServer)realtime?.send("SESSION_END");realtime?.stop();realtime=null;await saveCurrentConversation();if(state.anonymousSession&&state.match?.sessionId)await endMatch(state.anonymousSession.token,state.match.sessionId).catch(()=>{});const wasVideoMode=state.match?.mode==="video";state.match=null;pendingMessages.clear();finishingChat=false;if(destination!=="searching")state.chatMode="text";navigate(destination);if(destination==="searching"){if(wasVideoMode)state.chatMode="video";beginSearch();}}
function renderChatTimer(){if(!Number.isFinite(chatTimerRemaining))return;const timer=document.querySelector("#chat-timer");if(timer)timer.textContent=`${String(Math.floor(chatTimerRemaining/60)).padStart(2,"0")}:${String(chatTimerRemaining%60).padStart(2,"0")}`;}
function renderGuestWinTimer(){const remaining=state.guestWin.remainingSeconds;const timer=document.querySelector("#guest-win-timer");if(timer&&Number.isFinite(remaining))timer.textContent=`${String(Math.floor(remaining/60)).padStart(2,"0")}:${String(remaining%60).padStart(2,"0")}`;}
function stopGuestWinCountdown(){clearInterval(guestWinTimerInterval);guestWinTimerInterval=null;}
function startGuestWinCountdown(){stopGuestWinCountdown();const deadline=new Date(state.guestWin.claimDeadlineAt).getTime();const tick=()=>{const remaining=Math.max(0,Math.round((deadline-Date.now())/1000));state.guestWin.remainingSeconds=remaining;if(remaining<=0){stopGuestWinCountdown();if(state.guestWin.status==="won"){state.guestWin.status="expired";render();}return;}renderGuestWinTimer();};tick();guestWinTimerInterval=setInterval(tick,1000);}
let loadingGuestWinStatus=false;
async function loadGuestWinStatus(){if(loadingGuestWinStatus||state.accountSession)return;loadingGuestWinStatus=true;try{await ensureAnonymousSession();const result=await guestWinStatus(state.anonymousSession.token);if(result.claim_deadline){state.guestWin={status:"won",sparksReward:result.sparks_reward,claimDeadlineAt:result.claim_deadline,remainingSeconds:null};startGuestWinCountdown();if(routeName()==="home")render();}}catch{}finally{loadingGuestWinStatus=false;}}
async function playGuestWinAction(){if(state.accountSession||state.guestWin.status==="playing")return;state.guestWin.status="playing";render();try{await ensureAnonymousSession();const result=await playGuestWin(state.anonymousSession.token);if(result.won){state.guestWin={status:"won",sparksReward:result.sparks_reward,claimDeadlineAt:result.claim_deadline,remainingSeconds:null};startGuestWinCountdown();}else{state.guestWin={status:"lost",sparksReward:0,claimDeadlineAt:null,remainingSeconds:null};}}catch(error){state.guestWin={status:"error",sparksReward:0,claimDeadlineAt:null,remainingSeconds:null,message:friendlyError(error.message)};}render();}
async function claimGuestWinAction(session){if(state.guestWin.status!=="won")return;try{const result=await claimGuestWin({accountSession:session,anonId:state.identity.id});state.wallet={...state.wallet,balance:result.balance};state.accountMessage=`Welcome! ${result.sparks_reward} Sparks credited to your new account.`;state.guestWinJustClaimed=true;}catch{}finally{stopGuestWinCountdown();state.guestWin={status:"idle",sparksReward:0,claimDeadlineAt:null,remainingSeconds:null};}}
function stopAdWatchCountdown(){clearInterval(adWatchTimerInterval);adWatchTimerInterval=null;}
function startAdWatchCountdown(totalSeconds){stopAdWatchCountdown();let remaining=totalSeconds;const tick=()=>{if(document.visibilityState!=="visible"||!document.hasFocus())return;remaining-=1;const button=document.querySelector("#ad-earning-watch-btn");if(remaining<=0){stopAdWatchCountdown();state.adWatch.status="ready";state.adWatch.remainingSeconds=0;if(button){button.disabled=false;button.textContent="Claim reward";}return;}state.adWatch.remainingSeconds=remaining;if(button)button.textContent=`Watching… (${remaining}s)`;};adWatchTimerInterval=setInterval(tick,1000);}
async function startAdWatchAction(){if(["loading","watching","claiming"].includes(state.adWatch.status))return;state.adWatch={status:"loading"};render();const slotEl=document.querySelector("#ad-earning-slot");if(!slotEl){state.adWatch={status:"idle"};return;}const mounted=await mountRewardAdSlot(slotEl).catch(()=>false);if(!mounted){state.adWatch={status:"unavailable"};render();return;}adWatchRequestId=crypto.randomUUID();const dwellSeconds=state.adEarningConfig?.dwellSeconds||15;state.adWatch={status:"watching",remainingSeconds:dwellSeconds};const button=document.querySelector("#ad-earning-watch-btn");if(button){button.disabled=true;button.textContent=`Watching… (${dwellSeconds}s)`;}startAdWatchCountdown(dwellSeconds);}
