async function claimDailyStreakAction(){if(!state.accountSession||state.dailyStreakClaiming||state.dailyStreakStatus?.claimed_today)return;state.dailyStreakClaiming=true;render();try{const accountApi=await loadAccountApi();const result=await accountApi.claimDailyStreak(state.accountSession);state.wallet={...state.wallet,balance:result.balance};state.dailyStreakStatus={enabled:true,streak_count:result.streakCount,claimed_today:true,next_reward_credits:result.creditsAwarded};state.accountMessage=`${Math.floor(result.creditsAwarded/100)} Sparks credited — ${result.streakCount}-day streak!`;}catch(error){state.accountMessage=friendlyError(error.message);}finally{state.dailyStreakClaiming=false;}render();}
function handleRealtimeEvent(event){const payload=event.payload||{};if(event.type==="MESSAGE_RECEIVED")appendMessage("peer",String(payload.text||""));if(event.type==="MESSAGE_ACCEPTED"){const text=pendingMessages.get(event.eventId);if(text){appendMessage("me",text);pendingMessages.delete(event.eventId);}}if(event.type==="MESSAGE_REJECTED"||event.type==="RATE_LIMITED"){pendingMessages.delete(event.eventId);chatNotice(payload.message||payload.code||payload.reason||"Message was not accepted.");}if(event.type==="MATCH_COOLDOWN"){nextRequested=false;chatNotice(`You can find someone new in ${payload.remainingSeconds||1} seconds.`);}if(event.type==="TIMER_STATE"){if(Number.isFinite(payload.remainingSeconds)){chatTimerRemaining=Math.max(0,payload.remainingSeconds);renderChatTimer();clearInterval(chatTimerInterval);chatTimerInterval=setInterval(()=>{if(routeName()!=="chat"){clearInterval(chatTimerInterval);chatTimerInterval=null;return;}chatTimerRemaining=Math.max(0,chatTimerRemaining-1);renderChatTimer();},1000);}if(payload.idleWarning)chatNotice(payload.message||"Still there? Tap to stay available.",[["Stay available","ACTIVITY"]]);if(payload.idle===true)chatNotice("You were marked idle. Tap or type to become active again.",[["I'm here","ACTIVITY"]]);}if(event.type==="PEER_IDLE")chatNotice("The other person is idle. You can wait or choose Next.");if(event.type==="PEER_TYPING"){const indicator=document.querySelector("#peer-typing");if(indicator)indicator.hidden=!payload.typing;}if(event.type==="PEER_STREAMING_STATUS"&&payload.recording){const banner=document.querySelector("#peer-recording-banner");if(banner)banner.hidden=false;}if(event.type==="CONTINUE_REQUESTED")chatNotice(`Both people must accept to continue. Each delivered message costs ${payload.messageCredits||10} Credits.`,[["Continue","CONTINUE_ACCEPT"],["End","CONTINUE_DECLINE"]]);if(event.type==="CONTINUE_ACTIVATED"){chatNotice("Paid continuation is active.");enablePaidPhotoUI();}if(event.type==="PHOTO_RECEIVED")showDisappearingPhoto(payload.data,payload.durationSeconds);if(event.type==="PAYMENT_HOLD")chatNotice("Chat is paused because a payment could not be completed.");if(event.type==="CONTACT_UNLOCK_REQUEST")chatNotice(`The other person wants to unlock contact sharing for ${payload.costEach||500} Credits each.`,[["Accept","CONTACT_UNLOCK_ACCEPT"],["Decline","CONTACT_UNLOCK_DECLINE"]]);if(event.type==="CONTACT_UNLOCKED")chatNotice(`Contact sharing is unlocked for ${payload.seconds||300} seconds.`);if(event.type==="CONTACT_UNLOCK_ENDED")chatNotice("Contact sharing is locked again.");if(event.type==="LIKE_ACCEPTED")chatNotice("Like sent privately.");if(event.type==="LIKE_RECEIVED")chatNotice("They liked this chat 👍");if(event.type==="REPORT_ACCEPTED")chatNotice("Report received. This chat is ending.");if(event.type==="BLOCK_ACCEPTED")chatNotice("Blocked. This chat is ending.");if(event.type==="PEER_DISCONNECTED")chatNotice("The other person disconnected. Waiting briefly for them to return…");if(event.type==="PEER_RETURNED")chatNotice("");if(event.type==="SESSION_ENDED"){const destination=nextRequested?"searching":"history";nextRequested=false;finishChat(payload.reason,destination,false).catch(()=>{});}
if(event.type==="VIDEO_ELIGIBLE"){state.videoEligible=true;const panel=document.querySelector("#video-panel");if(panel)panel.hidden=false;if(payload.initiator)startVideoCall();}
if(event.type==="VIDEO_OFFER"){if(!videoCall){const panel=document.querySelector("#video-panel");if(panel)panel.hidden=false;videoCall=new VideoCallClient({send:(type,sendPayload)=>realtime?.send(type,sendPayload),onLocalStream:stream=>{const el=document.querySelector("#video-local");if(el)el.srcObject=stream;},onRemoteStream:stream=>{const el=document.querySelector("#video-remote");if(el)el.srcObject=stream;},onEnded:()=>stopVideoCall(false)});}videoCall.handleSignal("VIDEO_OFFER",payload).catch(error=>{chatNotice(error.message||"Could not start video.");stopVideoCall(false);});}
if(event.type==="VIDEO_ANSWER")videoCall?.handleSignal("VIDEO_ANSWER",payload).catch(()=>{});
if(event.type==="VIDEO_ICE_CANDIDATE")videoCall?.handleSignal("VIDEO_ICE_CANDIDATE",payload).catch(()=>{});
if(event.type==="VIDEO_END")stopVideoCall(false);
}
function monitorChatActivity(){activityCleanup?.();let lastSent=0;const signal=()=>{const now=Date.now();if(routeName()!=="chat"||now-lastSent<10000)return;if(realtime?.send("ACTIVITY"))lastSent=now;};const events=["pointerdown","touchstart","keydown","focus"];for(const type of events)window.addEventListener(type,signal,{passive:true});const visibility=()=>{if(document.visibilityState==="visible")signal();};document.addEventListener("visibilitychange",visibility);activityCleanup=()=>{for(const type of events)window.removeEventListener(type,signal);document.removeEventListener("visibilitychange",visibility);activityCleanup=null;};}
async function loadAuth(){return authModule??=await import("./auth.js")}
async function loadAccountApi(){return(accountApiModule??=await import("./account-api.js")).accountApi}
