function joinForumTopic(topicId){
  const topic=(state.forumTopics||[]).find(t=>t.id===topicId);
  if(!topic)return;
  stopForumSocket();
  state.activeForumTopic=topic;state.forumMessages=[];state.forumOnline=0;render();
  loadAccountApi().then(api=>{
    const wsUrl=api.forumSocketUrl(state.accountSession,topicId,state.identity.handle);
    const socket=new WebSocket(wsUrl);
    forumSocket=socket;
    socket.addEventListener("message",event=>{
      let payload;try{payload=JSON.parse(event.data);}catch{return;}
      if(socket!==forumSocket)return;
      if(payload.type==="HISTORY"){state.forumMessages=payload.payload.messages||[];render();scrollForumLog();}
      else if(payload.type==="MESSAGE"){state.forumMessages=[...state.forumMessages,payload.payload.message];render();scrollForumLog();}
      else if(payload.type==="PRESENCE"){state.forumOnline=payload.payload.online||0;render();}
    });
    socket.addEventListener("close",()=>{if(forumSocket===socket)forumSocket=null;});
  }).catch(()=>{});
}
